$fn = 48;
span = 180;
depth = 36;
panel_count = 6;
member_width = 6;
member_depth = 8;
gusset_radius = 9;
gusset_thickness = 2;
bolt_diameter = 2.5;

module member_between(p1, p2, w=member_width, d=member_depth) {
  dx = p2[0] - p1[0];
  dz = p2[1] - p1[1];
  L = sqrt(dx*dx + dz*dz);
  a = atan2(dz, dx);
  translate([(p1[0]+p2[0])/2, 0, (p1[1]+p2[1])/2])
    rotate([0, -a, 0]) cube([L, d, w], center=true);
}

module gusset_at(p) {
  difference() {
    translate([p[0], 0, p[1]]) cylinder(h=gusset_thickness, r=gusset_radius, center=true);
    translate([p[0], 0, p[1]]) cylinder(h=gusset_thickness+1, d=bolt_diameter, center=true);
  }
}

module support_pad(x) {
  translate([x, 0, -member_width]) cube([20, member_depth + 10, 3], center=true);
}

module simple_panel_truss() {
  pl = span / panel_count;
  union() {
    for (i=[0:panel_count-1]) {
      member_between([-span/2+i*pl,0], [-span/2+(i+1)*pl,0]);
      member_between([-span/2+i*pl,depth], [-span/2+(i+1)*pl,depth]);
    }
    for (i=[0:panel_count]) {
      x = -span/2 + i*pl;
      member_between([x,0], [x,depth]);
      gusset_at([x,0]);
      gusset_at([x,depth]);
    }
    support_pad(-span/2);
    support_pad(span/2);
  }
}

simple_panel_truss();

$fn = 96;

// ── Parameters ───────────────────────────────────────────
span    = 240;   // support-to-support distance (mm)
rise    =  80;   // height from tie beam to ridge (mm)
chord_d =   5;   // diameter — tie beam and rafter segments
web_d   =   4;   // diameter — king post and struts
joint_d =   8;   // diameter — node spheres

// ── Nodes ────────────────────────────────────────────────
A = [-span/2, 0,      0];   // left bearing
B = [ span/2, 0,      0];   // right bearing
C = [       0, 0,  rise];   // ridge / apex
D = [       0, 0,     0];   // king-post foot (tie-beam centre)

// Strut attachment nodes — midpoints of the two rafters
E = [-span/4, 0, rise/2];   // midpoint of rafter A→C
F = [ span/4, 0, rise/2];   // midpoint of rafter C→B

// ── Helpers ──────────────────────────────────────────────
module rod(p1, p2, d = 4) {
    v = p2 - p1;
    L = norm(v);
    translate(p1)
        rotate([0, acos(v[2] / L), atan2(v[1], v[0])])
            cylinder(d = d, h = L);
}

module node(p) { translate(p) sphere(d = joint_d); }

module member(p1, p2, d = 4) {
    rod(p1, p2, d);
    node(p1);
    node(p2);
}

// ── King-post truss ──────────────────────────────────────
module king_post_truss() {
    // Bottom tie beam (split at king-post foot D)
    member(A, D, chord_d);
    member(D, B, chord_d);

    // Left rafter — split at strut node E
    member(A, E, chord_d);
    member(E, C, chord_d);

    // Right rafter — split at strut node F
    member(C, F, chord_d);
    member(F, B, chord_d);

    // King post
    member(C, D, web_d);

    // Diagonal struts (king-post foot → rafter midpoints)
    member(D, E, web_d);
    member(D, F, web_d);
}

king_post_truss();

// Queen-Post Roof Truss
// OpenSCAD
// Units: mm

$fn = 40;

span = 260;
rise = 80;

chord_d = 5;
web_d = 4;
joint_d = 8;

A = [-span/2, 0, 0];
B = [ span/2, 0, 0];
C = [0, 0, rise];

D = [-span/4, 0, 0];
E = [ span/4, 0, 0];
F = [-span/4, 0, rise/2];
G = [ span/4, 0, rise/2];

module rod(p1, p2, d=4) {
    v = p2 - p1;
    L = norm(v);
    translate(p1)
        rotate([0, acos(v[2] / L), atan2(v[1], v[0])])
            cylinder(d=d, h=L);
}

module node(p) {
    translate(p)
        sphere(d=joint_d);
}

module member(p1, p2, d=4) {
    rod(p1, p2, d);
    node(p1);
    node(p2);
}

module queen_post_truss() {
    member(A, D, chord_d);
    member(D, E, chord_d);
    member(E, B, chord_d);

    member(A, C, chord_d);
    member(C, B, chord_d);

    member(D, F, web_d);
    member(E, G, web_d);

    member(F, G, chord_d);

    member(F, C, web_d);
    member(G, C, web_d);
}

queen_post_truss();

// Pratt Bridge / Roof Truss
// OpenSCAD
// Units: mm

$fn = 40;

span = 280;
height = 70;
bays = 8;

chord_d = 5;
web_d = 4;
joint_d = 8;

bay_w = span / bays;

module rod(p1, p2, d=4) {
    v = p2 - p1;
    L = norm(v);
    translate(p1)
        rotate([0, acos(v[2] / L), atan2(v[1], v[0])])
            cylinder(d=d, h=L);
}

module node(p) {
    translate(p)
        sphere(d=joint_d);
}

module member(p1, p2, d=4) {
    rod(p1, p2, d);
    node(p1);
    node(p2);
}

module pratt_truss() {
    for (i = [0:bays-1])
        member(
            [-span/2 + i * bay_w, 0, 0],
            [-span/2 + (i + 1) * bay_w, 0, 0],
            chord_d
        );

    for (i = [0:bays-1])
        member(
            [-span/2 + i * bay_w, 0, height],
            [-span/2 + (i + 1) * bay_w, 0, height],
            chord_d
        );

    for (i = [0:bays])
        member(
            [-span/2 + i * bay_w, 0, 0],
            [-span/2 + i * bay_w, 0, height],
            web_d
        );

    for (i = [0:floor(bays/2)-1])
        member(
            [-span/2 + i * bay_w, 0, height],
            [-span/2 + (i + 1) * bay_w, 0, 0],
            web_d
        );

    for (i = [floor(bays/2):bays-1])
        member(
            [-span/2 + i * bay_w, 0, 0],
            [-span/2 + (i + 1) * bay_w, 0, height],
            web_d
        );
}

pratt_truss();

// Warren Truss
// OpenSCAD
// Units: mm

$fn = 40;

span = 260;
height = 70;
bays = 8;

chord_d = 5;
web_d = 4;
joint_d = 8;

bay_w = span / bays;

module rod(p1, p2, d=4) {
    v = p2 - p1;
    L = norm(v);
    translate(p1)
        rotate([0, acos(v[2] / L), atan2(v[1], v[0])])
            cylinder(d=d, h=L);
}

module node(p) {
    translate(p)
        sphere(d=joint_d);
}

module member(p1, p2, d=4) {
    rod(p1, p2, d);
    node(p1);
    node(p2);
}

module warren_truss() {
    for (i = [0:bays-1]) {
        p1 = [-span/2 + i * bay_w, 0, 0];
        p2 = [-span/2 + (i + 1) * bay_w, 0, 0];
        member(p1, p2, chord_d);
    }

    for (i = [0:bays-1]) {
        p1 = [-span/2 + i * bay_w, 0, height];
        p2 = [-span/2 + (i + 1) * bay_w, 0, height];
        member(p1, p2, chord_d);
    }

    for (i = [0:bays-1]) {
        b1 = [-span/2 + i * bay_w, 0, 0];
        b2 = [-span/2 + (i + 1) * bay_w, 0, 0];
        t1 = [-span/2 + i * bay_w, 0, height];
        t2 = [-span/2 + (i + 1) * bay_w, 0, height];

        if (i % 2 == 0)
            member(b1, t2, web_d);
        else
            member(t1, b2, web_d);
    }

    member([-span/2, 0, 0], [-span/2, 0, height], chord_d);
    member([ span/2, 0, 0], [ span/2, 0, height], chord_d);
}

warren_truss();
